var indexList = null
function buildIndex() {
  if (indexList) return indexList
  indexList = []
  var lines = String(INDEX_TEXT).split('\n')
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i]
    if (!line) continue
    var tab1 = line.indexOf('\t')
    if (tab1 < 0) continue
    var tab2 = line.indexOf('\t', tab1 + 1)
    if (tab2 < 0) continue
    var name = line.slice(0, tab1)
    var artist = line.slice(tab1 + 1, tab2)
    var id = line.slice(tab2 + 1)
    if (name && id) indexList.push({ name: name, artist: artist, id: id })
  }
  return indexList
}

// 安全日志
function log() {
  try { console.log.apply(console, arguments) } catch (e) { /* ignore */ }
}

// 响应体转 JSON：兼容移动端(已自动parse/对象)与桌面端(字符串)
function toJson(body) {
  if (body == null) return null
  if (typeof body === 'string') {
    var t = body.trim()
    if (!t) return null
    try { return JSON.parse(t) } catch (e) { return null }
  }
  if (typeof body === 'object') {
    var isBin = false
    try {
      if (body.constructor && (body.constructor.name === 'Buffer' || body.constructor.name === 'Uint8Array')) isBin = true
      if (body.byteLength !== undefined || (body.buffer instanceof ArrayBuffer)) isBin = true
    } catch (e) { /* ignore */ }
    if (isBin) {
      try {
        var text = ''
        if (lxUtils && lxUtils.buffer && lxUtils.buffer.bufToString) text = lxUtils.buffer.bufToString(body, 'utf8')
        else text = body.toString ? String(body) : ''
        if (text) { try { return JSON.parse(text) } catch (e) { return null } }
      } catch (e) { /* ignore */ }
      return null
    }
    return body
  }
  return null
}

// HTTP 封装（回调对齐洛雪两参数/三参数）
function httpRequest(url, options) {
  options = options || {}
  return new Promise((resolve, reject) => {
    try {
      request(url, {
        method: options.method || 'GET',
        headers: Object.assign({
          'User-Agent': WEB_UA,
          'Referer': REFERER,
          'Accept': 'application/json',
        }, options.headers || {}),
        timeout: options.timeout || TIMEOUT,
        body: options.body,
      }, function (err, resp, body) {
        if (err) return reject(err)
        var b = resp && resp.body !== undefined ? resp.body : (body !== undefined ? body : '')
        resolve({ status: (resp && resp.statusCode) || 0, body: b })
      })
    } catch (e) { reject(e) }
  })
}

// 缓存工具
var seoCache = {}
function cacheGet(cache, key) {
  var e = cache[key]
  if (e && Date.now() - e.t < e.ttl) return e.v
  return null
}
function cacheSet(cache, key, val, ttl) {
  cache[key] = { t: Date.now(), ttl: ttl, v: val }
}

// ============ 索引匹配 ============
function cleanStr(s) {
  return String(s || '').replace(/\s+/g, '')
}

function buildKeyword(musicInfo) {
  var name = (musicInfo && (musicInfo.name || musicInfo.songName)) || ''
  var singer = musicInfo && (musicInfo.singer || musicInfo.singerName || musicInfo.artist || '')
  if (singer && typeof singer !== 'string') {
    try { singer = Array.isArray(singer) ? singer.join(' ') : String(singer) } catch (e) { singer = '' }
  }
  singer = singer || ''
  if (singer) return name + ' ' + singer
  return name
}

// 评分匹配：歌名精确4分/歌手3分/歌名包含2分，版本后缀惩罚
// 铁律：歌名必须至少包含匹配，仅歌手匹配一律拒绝（防止点A歌播B歌的错配）
function pickBest(items, name, singer) {
  if (!items || !items.length) return null
  var n = cleanStr(name)
  var s = cleanStr(singer)
  if (!n) return null
  var best = null
  var bestScore = -1
  for (var i = 0; i < items.length; i++) {
    var it = items[i]
    if (!it || !it.id) continue
    var iname = cleanStr(it.name)
    var iartist = cleanStr(it.artist)
    var base = iname.replace(/[（(][^（）()]*[)）]/g, '') // 去括号版本后缀
    var score = 0
    if (base === n) score += 4                 // 歌名精确（含去版本）
    else if (iname.indexOf(n) !== -1) score += 2 // 歌名包含
    else continue                              // 歌名不匹配 → 跳过（防错配）
    if (s) {
      // 双向包含: 索引歌手包含洛雪歌手 或 洛雪歌手包含索引歌手(合作曲目场景)
      if (iartist.indexOf(s) !== -1 || s.indexOf(iartist) !== -1) score += 3
    }
    if (/伴奏|KTV|karaoke|铃声/i.test(it.name)) score -= 2
    if (score > bestScore) { bestScore = score; best = it }
  }
  if (bestScore < 2) return null // 剩下的都是歌名匹配过的, 此处仅剩版本惩罚后不达标的
  return best
}

// 索引搜索（内置曲库线性评分扫描）
function matchSong(musicInfo) {
  var name = ((musicInfo && (musicInfo.name || musicInfo.songName)) || '').replace(/\s+/g, '')
  var singer = buildKeyword(musicInfo).replace(/\s+/g, '')
  var items = buildIndex()
  var best = pickBest(items, name, singer)
  if (best) return Promise.resolve(best)
  return Promise.reject(new Error('汽水热门曲库未收录该歌曲'))
}

// ============ H5 SEO 解析（播放+歌词共用） ============
function fetchSeoTrack(trackId) {
  var key = String(trackId)
  var hit = cacheGet(seoCache, key)
  if (hit) return Promise.resolve(hit)
  return httpRequest(LUNA_HOST + '/luna/h5/seo_track?track_id=' + encodeURIComponent(key) + '&device_platform=web')
    .then(({ body }) => {
      var json = toJson(body)
      if (!json || !json.track_player) throw new Error('汽水解析失败')
      cacheSet(seoCache, key, json, LYRIC_TTL)
      return json
    })
}

// 解析播放地址：video_model -> video_list -> 按音质选档
function resolvePlayUrl(trackId, quality) {
  return fetchSeoTrack(trackId).then((json) => {
    var vmStr = (json.track_player || {}).video_model
    if (!vmStr) throw new Error('汽水无播放信息')
    var vm
    try { vm = JSON.parse(vmStr) } catch (e) { throw new Error('video_model解析失败') }
    var list = vm.video_list || []
    if (!list.length) throw new Error('汽水无可用音质')
    // 档位按 video_meta.bitrate 从低到高排列, 取最高档
    var pick = list[list.length - 1]
    var url = (pick && (pick.main_url || pick.backup_url)) || ''
    if (!url || !/^https?:\/\//i.test(url)) throw new Error('汽水直链无效')
    return String(url).replace(/\\\//g, '/')
  })
}

// 汽水逐字歌词 -> 标准 LRC
// 行格式: [起始ms,持续ms]<偏移ms,时长ms,0>字<偏移,时长,0>字...
function qishuiLrcToLrc(raw) {
  if (!raw) return ''
  var lines = String(raw).split(/\r?\n/)
  var out = []
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i]
    var m = line.match(/^\[(\d+),(\d+)\]/)
    if (!m) { out.push(line); continue }
    var start = parseInt(m[1], 10)
    var text = line.slice(m[0].length).replace(/<\d+,\d+,\d+>/g, '')
    if (!text) continue
    var min = String(Math.floor(start / 60000)).padStart(2, '0')
    var sec = String(Math.floor((start % 60000) / 1000)).padStart(2, '0')
    var cs = String(Math.floor((start % 1000) / 10)).padStart(2, '0')
    out.push('[' + min + ':' + sec + '.' + cs + ']' + text)
  }
  return out.join('\n')
}

// 获取 LRC 歌词
function fetchLyric(trackId) {
  return fetchSeoTrack(trackId).then((json) => {
    var lrc = ((json.lyric || {}).content) || ''
    return qishuiLrcToLrc(lrc)
  })
}

// trackId 缓存：lyric 请求时 musicInfo 无 id，复用 musicUrl 阶段的结果
var tidCache = {}
function musicKey(musicInfo) {
  var mi = musicInfo || {}
  return String(mi.hash || mi.songmid || mi.id || (mi.name + (mi.singer || ''))) || ''
}

// ============ 各平台源 API ============
const apis = {}
;['kg', 'tx', 'wy', 'kw', 'mg'].forEach((src) => {
  apis[src] = {
    musicUrl(musicInfo, quality) {
      return matchSong(musicInfo).then((song) => {
        var k = musicKey(musicInfo)
        if (k) tidCache[k] = song.id
        return resolvePlayUrl(song.id, quality)
      })
    },
    lyric(musicInfo) {
      var k = musicKey(musicInfo)
      var tid = (k && tidCache[k]) || ''
      var p = tid ? Promise.resolve(tid) : matchSong(musicInfo).then((song) => song.id)
      return p
        .then((id) => fetchLyric(id))
        .then((lrc) => ({ lyric: lrc, tlyric: '' }))
        .catch(() => ({ lyric: '', tlyric: '' }))
    },
  }
})

// 注册应用 API 请求事件
on(EVENT_NAMES.request, ({ source, action, info }) => {
  var api = apis[source]
  if (!api) return Promise.reject('不支持的音乐源: ' + source)
  switch (action) {
    case 'musicUrl':
      if (!info || !info.musicInfo || !info.type) return Promise.reject('参数不完整')
      return api.musicUrl(info.musicInfo, info.type).catch((err) => {
        log('[汽水音乐] musicUrl 失败:', err && err.message)
        return Promise.reject(err)
      })
    case 'lyric':
      if (!info || !info.musicInfo) return Promise.reject('参数不完整')
      return api.lyric(info.musicInfo)
    default:
      return Promise.reject('action not support: ' + action)
  }
})

// 初始化完成
send(EVENT_NAMES.inited, {
  status: true,
  sources: {
    kg: { name: '汽水音乐', type: 'music', actions: ['musicUrl', 'lyric'], qualitys: QUALITYS },
    tx: { name: '汽水音乐', type: 'music', actions: ['musicUrl', 'lyric'], qualitys: QUALITYS },
    wy: { name: '汽水音乐', type: 'music', actions: ['musicUrl', 'lyric'], qualitys: QUALITYS },
    kw: { name: '汽水音乐', type: 'music', actions: ['musicUrl', 'lyric'], qualitys: QUALITYS },
    mg: { name: '汽水音乐', type: 'music', actions: ['musicUrl', 'lyric'], qualitys: QUALITYS },
  },
})